import{_ as l,c as a,o as t,ag as e}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"서울문화재단 무기계약직 직원 운영 규정","description":"","frontmatter":{"title":"서울문화재단 무기계약직 직원 운영 규정","subtitle":"","doc_id":"","last_update":"2017-06-09","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/310_서울문화재단 무기계약직 직원 운영 규정(170609).md","filePath":"regulation/310_서울문화재단 무기계약직 직원 운영 규정(170609).md"}'),o={name:"regulation/310_서울문화재단 무기계약직 직원 운영 규정(170609).md"};function i(s,r,n,d,c,p){return t(),a("div",null,r[0]||(r[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">서울문화재단 무기계약직 직원 운영 규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;서울문화재단 무기계약직 직원 운영 규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2013.   3.  27  개정 2013.   4.  25  개정 2013.   8.  29
개정 2014.   7.  21  개정 2015.   9.  21<span style="visibility:hidden;">                     </span>
개정 2016.  10.   7  개정 2017.   6.   9<span style="visibility:hidden;">                     </span></pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인 서울문화재단(이하 “재단”이라 한다)의 정관 및 인사규정 제12조 4항에서 규정으로 정하도록 위임한 재단 무기계약직 직원의 인사에 관한 사항과 그 시행에 필요한 사항을 정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 무기계약직 직원의 인사 및 운영 등에 관하여 법령과 정관, 직제규정 및 다른 규정에서 별도로 정하는 경우를 제외하고는 이 규정에서 정하는 바에 따른다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (용어의 정의) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (용어의 정의) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(용어의 정의)</strong> 이 규정에서 사용되는 용어의 정의는 다음과 같다.</p><ol><li>“무기계약직 직원”이라 함은 재단 기간제계약직 직원을 대상으로, 평가를 통해 상시ㆍ지속적 업무에 종사하며 기간을 정하지 않은 근로계약을 체결한 자를 말한다. &lt;개정 2016. 10. 7.&gt;</li><li>“상시ㆍ지속적 업무”라 함은 연중 계속되는 업무로 재단 내 유사ㆍ동일한 업무가 향후에도 2년 이상 지속될 것이 예상되는 업무를 말한다.</li></ol><h2 id="article4" class="sr-only" tabindex="-1">제4조 (인사관리) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (인사관리) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(인사관리)</strong> 무기계약직 직원의 임용, 보직, 복무, 근무평정, 상벌 등에 관한 사항은 인사담당부서에서 총괄 관리한다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (정원) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (정원) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(정원)</strong> ① 재단은 무기계약직 직원의 운용 및 관리를 위해, 별도 정원을 둘 수 있다.<br> ② 무기계약직 직원의 정원은 별표 1과 같다.<br> ③ 재단은 제②항에서 정한 무기계약직 총 정원의 한도 내에서 정원 내 결원의 보충, 업무량 및 사업의 활용계획에 따라 인력을 탄력적으로 조정하여 운영할 수 있다. &lt;개정 2013. 4. 25.&gt;</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (임용) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (임용) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(임용)</strong> ① 무기계약직 직원의 임용은 정원 내 결원의 보충 및 사업의 활용계획 및 운영실적 등에 따르며, 이에 관한 사항은 인사담당부서에서 관리한다.<br> ② 무기계약직 직원의 임용은 관련법령 및 재단의 무기계약직 전환계획에 따라 인사위원회의 무기계약직 전환심의를 거친 후 대표이사가 확정한다.<br> ③ 기타 무기계약직 직원의 임용과 관련된 사항은 재단 인사규정을 준수한다.<br> &lt;개정 2013. 4. 25.&gt;</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (무기계약직의 전환) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (무기계약직의 전환) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(무기계약직의 전환)</strong> ① 재단은 주무부서와의 협의를 거쳐 상시ㆍ지속적 업무에 종사하며 정규직과 동종 또는 유사한 업무에 종사하는 기간제계약직 직원 중 근무성적이 우수한 직원 중 최초 근로계약일을 기준으로 2년이 경과하는 직원을 무기계약직 직원으로 전환할 수 있다. &lt;개정 2016. 10. 7.&gt;<br> ② 무기계약직 직원의 전환은 개인별 근무평가 및 복무태도 등을 평가 후 인사위원회 심의를 거친 후 대표이사가 확정한다.<br> ③ 이 규정에서 정한 사항 외 무기계약직 직원으로의 전환과 관련한 세부절차는 재단의 계약직 직원 운영에 관한 내규 제2장 을 준용하며, 준용시 위 내규의 본문상 일반계약직은 기간제계약직으로, 정규직은 무기계약직으로 적용한다. &lt;개정 2013. 4. 25., 2016. 10. 7.&gt;</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (계약의 해지) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (계약의 해지) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(계약의 해지)</strong> ① 무기계약직 직원이 재단 인사규정 제9조 채용 결격사유에 해당하거나, 정년의 도달ㆍ사망하였을 경우 근로계약은 당연이 해지된다.<br> ② 무기계약직 직원이 퇴직하고자 하는 경우에는 사직원을 제출하여 대표이사의 승인을 받아야 한다. 단, 재단 인사규정 제18조에 따라 직위해제된 자와 제36조에 따라 징계의결요구 중인 자는 징계처분의 확정 및 당해 사건에 대한 확정판결이 있기 전까지는 퇴직할 수 없다.<br> ③ 무기계약직 직원이 다음 각 호의 어느 하나에 해당하는 경우에는 인사위원회의 의결을 거쳐 대표이사가 면직시킬 수 있다.</p><ol><li>직제와 정원이 개정되거나 폐지된 경우 및 예산의 감소로 직위가 없어지거나 과원이 된 때</li><li>휴직기간이 끝나거나 휴직사유가 소멸된 후에도 직무에 복귀하지 아니하거나 복귀 후에도 직무를 감당할 수 없을 때</li><li>1개월간 특별한 사유 없이 10일 이상 무계 결근한 때</li><li>형사사건으로 기소된 사람이 금고이상의 형을 받았을 때</li><li>징병검사ㆍ입영 또는 소집의 명령을 받고 정당한 이유 없이 이를 기피하거나 군복무를 위하여 휴직 중인 사람이 군복무 중 군무를 이탈하였을 때</li><li>업무상 부상 또는 질병으로 요양 중인 직원에 대하여 관계법령에 따라 일시보상을 한 때</li><li>직무수행에 필요한 자격증의 효력이 상실되거나 면허가 취소되어 담당직무를 수행할 수 없게 된 때</li><li>인사규정 제18조에 따라 직위 해제된 사람이 6개월이 지나도 직위를 부여받지 못하였을 때</li><li>허위 또는 부정한 방법으로 임용되었음이 발견된 때<br> ④ 제3항에 따라 직원을 면직하는 경우에는 인사위원회의 의결을 거쳐야 한다. &lt;개정 2013. 4. 25.&gt;</li></ol><h2 id="article9" class="sr-only" tabindex="-1">제9조 (보직) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (보직) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(보직)</strong> ① 대표이사는 재단의 효율적 운영을 위하여 무기계약직 직원에게 전공분야, 경력, 훈련, 전문성 및 적성 등을 고려하여 직위를 부여할 수 있다.<br> ② 대표이사가 필요하다고 판단하는 경우 기관의 실정에 맞게 업무성격이 동일하거나 유사한 직종간 배치전환을 통한 순환보직을 명할 수 있다. &lt;개정 2013. 4. 25.&gt;</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (임금) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (임금) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(임금)</strong> 무기계약직 직원의 보수는 재단 보수규정을 따른다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (근무평정) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (근무평정) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(근무평정)</strong> ① 대표이사는 정기 또는 수시로 무기계약직 직원의 근무성적을 객관적이고 엄정하게 평정하여 인사관리에 반영할 수 있다.<br> ② 무기계약직 직원의 근무평정에 관한 사항은 재단 인사규정 및 관련 내규에 따른다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (상벌) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (상벌) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(상벌)</strong> 재단은 관련 규정에 따라 무기계약직 직원에게 포상 및 징계를 할 수 있다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (무기계약직 직원 인사위원회의 설치) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (무기계약직 직원 인사위원회의 설치) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(무기계약직 직원 인사위원회의 설치)</strong> ① 재단은 무기계약직 직원의 공정한 인사관리를 위하여 인사위원회를 둘 수 있다.<br> ② 무기계약직 직원 인사위원회는 재단 인사규정 제45조에 따른 인사위원과 동일하게 구성함을 원칙으로 하되, 필요에 따라 대표이사는 별도의 위원으로 무기계약직 직원 인사위원회를 구성할 수 있다.<br> ③ 기타 무기계약직 직원 인사위원회의 설치 및 운영에 관한 사항은 재단 인사규정을 따른다.</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (무기계약직 직원 인사위원회의 기능) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (무기계약직 직원 인사위원회의 기능) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(무기계약직 직원 인사위원회의 기능)</strong> 무기계약직 직원 인사위원회는 다음 사항을 심의 결정한다.</p><ol><li>무기계약직 직원 채용 및 신분변동에 관한 사항</li><li>무기계약직 직원의 표창 및 징계에 관한 사항</li><li>직권면직에 관한 사항</li><li>연봉의 재심의에 관한 사항</li><li>기타 대표이사가 무기계약직 직원의 인사에 관하여 심의를 요구한 사항</li></ol><h2 id="article15" class="sr-only" tabindex="-1">제15조 (성실의무) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (성실의무) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(성실의무)</strong> 무기계약직 직원은 재단의 제 규정을 준수하고 업무상 지시에 따라 맡은 바 직무를 성실히 수행하여야 한다.</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (신분보장) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (신분보장) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(신분보장)</strong> 무기계약직 직원은 형의 선고, 징계처분 또는 재단 인사규정에서 정한 바에 의하지 아니하고는 그 의사에 반하여 휴직, 면직 또는 기타 불이익한 처분을 받지 아니한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 규정은 2013년 3월 27일 부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 4. 25.&gt;<br> 제1조(시행일) 이 규정은 2013년 4월 25일 부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 8. 29.&gt;<br> 제1조(시행일) 이 규정은 2013년 4월 25일 부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2016. 10. 7.&gt;<br> 제1조(시행일) 이 규정은 2016년 10월 7일 부터 시행한다.</p><p><strong>[별표 1]</strong> &lt;개정 2015. 9. 21., 2017. 6. 9.&gt;</p><p>서울문화재단 무기계약직 직원 정원표</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:159px;"><col style="width:159px;"><col style="width:159px;"><col style="width:159px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:left;"></p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:center;">3∼5급 상당</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:center;">6~7급 상당</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:center;">총계</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">정 원</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">-</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">2명</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">2명</p></th></tr></table>`,48)]))}const g=l(o,[["render",i]]);export{b as __pageData,g as default};
